import{_ as t,C as r,o as n,c as l,j as a,a as s,E as i,aj as c}from"./chunks/framework.m090XgxO.js";const x=JSON.parse('{"title":"对话页","description":"","frontmatter":{},"headers":[],"relativePath":"examples/chat-page.md","filePath":"examples/chat-page.md","lastUpdated":1788635489000}'),p={name:"examples/chat-page.md"};function d(m,e,h,f,_,g){const o=r("XhDemo");return n(),l("div",null,[e[0]||(e[0]=a("h1",{id:"对话页",tabindex:"-1"},[s("对话页 "),a("a",{class:"header-anchor",href:"#对话页","aria-label":'Permalink to "对话页"'},"​")],-1)),e[1]||(e[1]=a("p",null,"一条助手回复里同时摆着思考过程、工具调用、流式正文、代码块与批准闸门，外面是消息流与提示输入框。",-1)),i(o,{src:"examples/04-chat-page"}),e[2]||(e[2]=c('<h2 id="这一屏定了什么" tabindex="-1">这一屏定了什么 <a class="header-anchor" href="#这一屏定了什么" aria-label="Permalink to &quot;这一屏定了什么&quot;">​</a></h2><ul><li><strong>一条消息是一个容器，里面爱放几件放几件。</strong> <a href="./../components/message-feed">消息流</a>只管集合语义、粘底跟随与那一个播报区；气泡、头像、时间、回复内部的结构全由你写。</li><li><strong>五件东西共用一个间距档。</strong> 思考过程、工具调用、正文、代码块、闸门竖着排，彼此的空隙是同一个值——这一档不统一，一条回复就会看着像五张卡片拼起来的。</li><li><strong>闸门不藏进折叠里。</strong> <a href="./../components/approval">审批</a>常驻在回复末尾：必选范围没勾满就批不了，勾选与判定是原子的，不存在「已批准但范围还没同步」的窗口。</li><li><strong>状态由数据说了算。</strong> 思考过程给了起止时刻就自己显示「想了几秒」，<a href="./../components/tool-call">工具调用</a>按阶段换状态文案，<a href="./../components/code-view">代码视图</a>标了 <code>complete</code> 才放心着色——组件不猜，宿主给什么它显示什么。</li><li><strong>发送键原位变停止。</strong> <a href="./../components/prompt-input">提示输入框</a>在生成期间把提交键换成停止，输入框仍可编辑：用户还要能改下一句。</li></ul><h2 id="换成你的项目" tabindex="-1">换成你的项目 <a class="header-anchor" href="#换成你的项目" aria-label="Permalink to &quot;换成你的项目&quot;">​</a></h2><ul><li>正文走<a href="./../runtime/markdown">流式 Markdown</a>：渲染器是有状态的，一个实例只喂同一条消息的全文。</li><li>不分条、只往下追加的输出（构建日志、命令回显）用<a href="./../components/log">日志</a>，它和消息流一样粘底，但不承担会话语义。</li><li>消息条目上有 <code>data-role</code>，助手与用户两侧的排布差异按它写，不必给两套组件。</li></ul>',4))])}const P=t(p,[["render",d]]);export{x as __pageData,P as default};
